select CAST(id AS String) as id, CAST(type AS String) as type, CAST(source AS String) as source, nullIf(CAST(subject AS String), '') as subject, time as time, nullIf(CAST(traceparent AS String), '') as traceparent, nullIf(CAST(tracestate AS String), '') as tracestate, nullIf(CAST(provider AS String), '') as provider, nullIf(CAST(model AS String), '') as model, nullIf(CAST(model_id AS String), '') as model_id, nullIf(CAST(request_mode AS String), '') as request_mode, nullIf(CAST(region AS String), '') as region, nullIf(CAST(client AS String), '') as client, input_tokens as input_tokens, input_text_tokens as input_text_tokens, input_audio_tokens as input_audio_tokens, input_image_tokens as input_image_tokens, input_cache_read_tokens as input_cache_read_tokens, input_cache_read_text_tokens as input_cache_read_text_tokens, input_cache_read_audio_tokens as input_cache_read_audio_tokens, input_cache_read_image_tokens as input_cache_read_image_tokens, input_cache_read_video_tokens as input_cache_read_video_tokens, input_cache_write_tokens as input_cache_write_tokens, input_cache_write_text_tokens as input_cache_write_text_tokens, input_cache_write_audio_tokens as input_cache_write_audio_tokens, input_cache_write_image_tokens as input_cache_write_image_tokens, input_cache_write_video_tokens as input_cache_write_video_tokens, output_tokens as output_tokens, output_text_tokens as output_text_tokens, output_audio_tokens as output_audio_tokens, output_reasoning_tokens as output_reasoning_tokens, accepted_prediction_tokens as accepted_prediction_tokens, rejected_prediction_tokens as rejected_prediction_tokens, realtime_audio_ms as realtime_audio_ms, reported_total_tokens as reported_total_tokens, nullIf(CAST(semantic_cache_status AS String), '') as semantic_cache_status, nullIf(CAST(semantic_cache_embeddings_provider AS String), '') as semantic_cache_embeddings_provider, nullIf(CAST(semantic_cache_embeddings_model AS String), '') as semantic_cache_embeddings_model, nullIf(semantic_cache_embeddings_tokens, 0) as semantic_cache_embeddings_tokens, nullIf(CAST(compression_status AS String), '') as compression_status, nullIf(compression_input_tokens_before, 0) as compression_input_tokens_before, CAST(reported_cost_usd AS Decimal(38, 9)) as reported_cost_usd, CAST(reported_cache_cost_usd AS Decimal(38, 9)) as reported_cache_cost_usd, teams as teams, nullIf(toString(workspace_id), '00000000-0000-0000-0000-000000000000') as workspace_id, nullIf(toString(service_id), '00000000-0000-0000-0000-000000000000') as service_id, nullIf(toString(route_id), '00000000-0000-0000-0000-000000000000') as route_id, nullIf(toString(plugin_id), '00000000-0000-0000-0000-000000000000') as plugin_id, nullIf(toString(consumer_id), '00000000-0000-0000-0000-000000000000') as consumer_id, arrayMap(value -> toString(value), consumer_group_ids) as consumer_group_ids, nullIf(toString(application_id), '00000000-0000-0000-0000-000000000000') as application_id, nullIf(CAST(request_id AS String), '') as request_id, CAST(tags AS Map(String, String)) as tags
from (
  select id, type, source, subject, time, traceparent, tracestate, provider, model, model_id, request_mode, region, client, input_tokens, input_text_tokens, input_audio_tokens, input_image_tokens, input_cache_read_tokens, input_cache_read_text_tokens, input_cache_read_audio_tokens, input_cache_read_image_tokens, input_cache_read_video_tokens, input_cache_write_tokens, input_cache_write_text_tokens, input_cache_write_audio_tokens, input_cache_write_image_tokens, input_cache_write_video_tokens, output_tokens, output_text_tokens, output_audio_tokens, output_reasoning_tokens, accepted_prediction_tokens, rejected_prediction_tokens, realtime_audio_ms, reported_total_tokens, semantic_cache_status, semantic_cache_embeddings_provider, semantic_cache_embeddings_model, semantic_cache_embeddings_tokens, compression_status, compression_input_tokens_before, reported_cost_usd, reported_cache_cost_usd, teams, workspace_id, service_id, route_id, plugin_id, consumer_id, consumer_group_ids, application_id, request_id, tags
  from usage_events final
  where tenant_id = toUUID('00000000-0000-4000-8000-000000000001') and time >= toDateTime64('2026-10-06 00:00:00.000', 3, 'UTC') and time < toDateTime64('2026-10-07 00:00:00.000', 3, 'UTC') and provider = 'anthropic'
)
order by toStartOfMinute(time), time, source, id
